import gurobipy as gp
from gurobipy import GRB
requirements = []
for rec in LEGACY_RECORDS:
    req = rec['values']['Requirement']
    requirements.append(int(req))
T = len(requirements)
if T != 48:
    raise ValueError(f'Expected 48 time slots, got {T}')
m = gp.Model('Waitstaff_Scheduling')
x = m.addVars(range(T), lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((x[t] for t in range(T))), GRB.MINIMIZE)
for s in range(T):
    covering = []
    for k in range(16):
        t = (s - k) % T
        covering.append(x[t])
    m.addConstr(gp.quicksum(covering) >= requirements[s], name=f'req_{s + 1}')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for t in range(T):
        print(f'x[{t + 1}]: {x[t].X}')
else:
    print(f'Solver status: {m.Status}')